const notificationId = crypto.randomUUID();

// Create the final notification object, including its own ID.
const notification = {
    id: notificationId, // <-- The important addition
    ...notificationDetails
};

// Add it to the map.
this.notificationMap.set(notificationId, notification);
this.notificationCount++;

if (notification.dismissIn) {
    this.$timeout(() => this.dismiss(notification), notification.dismissIn);
}

// 1. Validate the input.
if (!notification || !notification.id) {
        return;
}

const FADE_OUT_DURATION_MS = 500; // 0.5 seconds
const notificationId = notification.id;

// 2. Get the actual notification object that is stored in the Map.
const notificationInMap = this.notificationMap.get(notificationId);

// 3. Check if the notification exists and is not already in the process of dismissing.
//    This prevents errors if the dismiss button is clicked multiple times.
if (notificationInMap && !notificationInMap.isDismissingAlert) {
        // 4. Set the flag to true. This will trigger the CSS animation.
        notificationInMap.isDismissingAlert = true;

        // 5. Use $timeout to wait for the animation to finish before removing the notification.
        //    The duration here MUST match your CSS animation/transition duration.
        this.$timeout(() => {
                this.notificationMap.delete(notificationId);
                this.notificationCount--;
        }, FADE_OUT_DURATION_MS);
}
